package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.helper.HttpConnection;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Document;
import org.jsoup.parser.Tag;
import org.jsoup.select.Elements;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class FormElement_formData_TriageGen1Test {

    private Document doc;
    private FormElement form;

    @Before
    public void setUp() {
        doc = Document.create("");
        form = doc.createElement("form");
        doc.body().appendChild(form);
    }

    @Test
    public void testFormData_EmptyForm() {
        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_SkipNonSubmittable() {
        Element div = doc.createElement("div");
        div.attr("name", "divName");
        // Assuming div.tag().isFormSubmittable() is false
        form.appendChild(div);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_SkipDisabled() {
        Element input = doc.createElement("input");
        input.attr("name", "test");
        input.attr("disabled", "disabled");
        form.appendChild(input);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_SkipNoName() {
        Element input = doc.createElement("input");
        input.attr("type", "text");
        // name is empty
        form.appendChild(input);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_StandardInput() {
        Element input = doc.createElement("input");
        input.attr("name", "username");
        input.attr("type", "text");
        input.text("john_doe"); 
        // Note: el.val() usually returns the value attribute in jsoup for inputs
        input.attr("value", "john_doe");
        form.appendChild(input);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("username", result.get(0).getKey());
        Assert.assertEquals("john_doe", result.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithSelectedOption() {
        Element select = doc.createElement("select");
        select.attr("name", "gender");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "male");
        opt1.text("Male");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "female");
        opt2.attr("selected", "selected");
        opt2.text("Female");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("gender", result.get(0).getKey());
        Assert.assertEquals("female", result.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithMultipleSelected() {
        Element select = doc.createElement("select");
        select.attr("name", "colors");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "red");
        opt1.attr("selected", "selected");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "blue");
        opt2.attr("selected", "selected");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(2, result.size());
        Assert.assertEquals("red", result.get(0).getValue());
        Assert.assertEquals("blue", result.get(1).getValue());
    }

    @Test
    public void testFormData_SelectWithNoSelectedFallback() {
        Element select = doc.createElement("select");
        select.attr("name", "choice");

        Element opt1 = doc.createElement("option");
        opt1.attr("value", "first");

        Element opt2 = doc.createElement("option");
        opt2.attr("value", "second");

        select.appendChild(opt1);
        select.appendChild(opt2);
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("first", result.get(0).getValue());
    }

    @Test
    public void testFormData_SelectWithNoOptions() {
        Element select = doc.createElement("select");
        select.attr("name", "empty_select");
        form.appendChild(select);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_CheckboxCheckedWithValue() {
        Element checkbox = doc.createElement("input");
        checkbox.attr("type", "checkbox");
        checkbox.attr("name", "agree");
        checkbox.attr("value", "yes");
        checkbox.attr("checked", "checked");
        form.appendChild(checkbox);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("agree", result.get(0).getKey());
        Assert.assertEquals("yes", result.get(0).getValue());
    }

    @Test
    public void testFormData_CheckboxCheckedNoValue() {
        Element checkbox = doc.createElement("input");
        checkbox.attr("type", "checkbox");
        checkbox.attr("name", "subscribe");
        checkbox.attr("checked", "checked");
        form.appendChild(checkbox);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("subscribe", result.get(0).getKey());
        Assert.assertEquals("on", result.get(0).getValue());
    }

    @Test
    public void testFormData_CheckboxUnchecked() {
        Element checkbox = doc.createElement("input");
        checkbox.attr("type", "checkbox");
        checkbox.attr("name", "uncheck_me");
        form.appendChild(checkbox);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }

    @Test
    public void testFormData_RadioChecked() {
        Element radio = doc.createElement("input");
        radio.attr("type", "radio");
        radio.attr("name", "gender");
        radio.attr("value", "m");
        radio.attr("checked", "checked");
        form.appendChild(radio);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertEquals(1, result.size());
        Assert.assertEquals("gender", result.get(0).getKey());
        Assert.assertEquals("m", result.get(0).getValue());
    }

    @Test
    public void testFormData_RadioUnchecked() {
        Element radio = doc.createElement("input");
        radio.attr("type", "radio");
        radio.attr("name", "gender");
        radio.attr("value", "m");
        form.appendChild(radio);

        List<Connection.KeyVal> result = form.formData();
        Assert.assertTrue(result.isEmpty());
    }
}
